import sys
from datetime import date

from books import Catalogue
from loans import Ledger


def main():
    catalogue = Catalogue()
    ledger = Ledger(catalogue)
    for raw in sys.stdin:
        p = raw.split()
        if not p:
            continue
        try:
            if p[0] == "BOOK" and len(p) == 3:
                print(f"book {p[1]}: {catalogue.add(p[1], int(p[2]))} copies")
            elif p[0] == "ISSUE" and len(p) == 4:
                print(ledger.issue(p[1], p[2], date.fromisoformat(p[3])))
            elif p[0] == "RETURN" and len(p) == 4:
                print(ledger.give_back(p[1], p[2], date.fromisoformat(p[3])))
            elif p[0] == "OVERDUE" and len(p) == 2:
                rows = ledger.overdue(date.fromisoformat(p[1]))
                print("\n".join(rows) if rows else "nothing overdue")
            elif p[0] == "AVAILABLE" and len(p) == 2:
                print(f"{p[1]}: {catalogue.available(p[1])} available")
            else:
                print(f"error: bad command {raw.strip()}")
        except ValueError:
            print(f"error: bad value in {raw.strip()}")


main()

