class Catalogue:
    def __init__(self):
        self._copies = {}        # code -> copies owned
        self._out = {}           # code -> copies issued now

    def add(self, code, copies):
        self._copies[code] = self._copies.get(code, 0) + copies
        return self._copies[code]

    def known(self, code):
        return code in self._copies

    def available(self, code):
        return self._copies.get(code, 0) - self._out.get(code, 0)

    def take(self, code):
        self._out[code] = self._out.get(code, 0) + 1

    def give_back(self, code):
        self._out[code] -= 1

from datetime import date, timedelta

from books import Catalogue

LOAN_DAYS = 14
FINE_PER_DAY = 5
MAX_BOOKS = 3


class Ledger:
    def __init__(self, catalogue: Catalogue):
        self.catalogue = catalogue
        self._loans = {}         # (code, member) -> due date

    def _held_by(self, member):
        return sum(1 for (_, m) in self._loans if m == member)

    def issue(self, code, member, day: date):
        if not self.catalogue.known(code):
            return f"error: no book {code}"
        if (code, member) in self._loans:
            return f"error: {member} already has {code}"
        if self.catalogue.available(code) == 0:
            return f"error: no copies of {code} left"
        if self._held_by(member) >= MAX_BOOKS:
            return f"error: {member} already has {MAX_BOOKS} books"
        due = day + timedelta(days=LOAN_DAYS)
        self._loans[(code, member)] = due
        self.catalogue.take(code)
        return f"issued {code} to {member}, due {due.isoformat()}"

    def give_back(self, code, member, day: date):
        due = self._loans.pop((code, member), None)
        if due is None:
            return f"error: {code} is not with {member}"
        self.catalogue.give_back(code)
        late = max(0, (day - due).days)
        return f"returned {code}, fine {late * FINE_PER_DAY}"

    def overdue(self, day: date):
        rows = [((day - due).days, member, code) for (code, member), due in self._loans.items() if day > due]
        rows.sort(key=lambda r: (-r[0], r[1], r[2]))
        return [f"{member} {code} {days} days" for days, member, code in rows]
